2	package darksafe
3	
4	// Subject is an identity that can request access to a resource.
5	type Subject struct {
6		ID       string
7		Kind     string // "user", "service", "external"
8		Roles    []string
9		Disabled bool
10	}
11	
12	// Resource is a protected object with a scope path.
13	type Resource struct {
14		ID    string
15		Scope string // e.g. "org/payments/ledger"
16	}
17	
18	// Decision explains one access evaluation.
19	type Decision struct {
20		Allowed bool
21		Reason  string
22		Matched []string
23		// Version is the policy version actually used, 0 when no published
24		// version was evaluated (legacy Access and early rejections).
25		Version int
26	}
27	
28	// Access evaluates a request and always returns an explanation.
29	func Access(subject Subject, resource Resource, action string) Decision {
30		if subject.Disabled {
31			return Decision{Allowed: false, Reason: "subject is disabled"}
32		}
33		if subject.ID == "" || resource.ID == "" || action == "" {
34			return Decision{Allowed: false, Reason: "incomplete request"}
35		}
36		needed := action + ":" + resource.Scope
37		for _, role := range subject.Roles {
38			if role == "owner" || role == resource.Scope+":"+action {
39				return Decision{Allowed: true, Reason: "role grants " + needed, Matched: []string{role}}
40			}
41		}
42		return Decision{Allowed: false, Reason: "no role grants " + needed}
43	}
